use std::{collections::HashSet,path::Path};
use serde_json::{json,Value};
use symbolica::{atom::{Atom,AtomCore},id::Replacement};
fn main(){std::thread::Builder::new().stack_size(128*1024*1024).spawn(run).unwrap().join().unwrap();}
fn run(){
 let base=Path::new("target/cli-coefficient-optimization");let ns="coefficient_dimension_proof";let lambda=Atom::parse("scale_dimension_probe",ns,Default::default()).unwrap();let mut cases=Vec::new();
 for(case,numerator_dimension)in [("ggh",3u32),("gghh",4),("gghhh",5),("gggg-up",4)]{
  let graph:Value=serde_json::from_slice(&std::fs::read(base.join(format!("qualification/{case}/prepared-graph.json"))).unwrap()).unwrap();let results:Value=serde_json::from_slice(&std::fs::read(base.join(format!("qualification/{case}/outputs.json"))).unwrap()).unwrap();
  let names=graph["parameters"].as_array().unwrap();let qualified:Vec<_>=names.iter().map(|v|Atom::parse(v.as_str().unwrap(),ns,Default::default()).unwrap()).collect();let short_names:Vec<_>=qualified.iter().map(ToString::to_string).collect();let parameters:Vec<_>=short_names.iter().map(|s|Atom::parse(s,ns,Default::default()).unwrap()).collect();assert_eq!(parameters.iter().collect::<HashSet<_>>().len(),parameters.len(),"displayed parameter collision");
  let dimensions:Vec<_>=names.iter().map(|name|{let name=name.as_str().unwrap();if name.contains("::P(")||name.ends_with("::MT")||name.ends_with("::MU")||name.ends_with("::ZERO"){1}else if name.ends_with("::G")||name.ends_with("::yt")||name.contains("::ϵ(")||name.contains("::ϵbar("){0}else{panic!("unclassified physical parameter {name}")}}).collect();
  let replacements:Vec<_>=parameters.iter().zip(&dimensions).filter(|(_,d)|**d==1).map(|(p,_)|Replacement::new(p.clone(),lambda.clone()*p.clone())).collect();let terms=graph["terms"].as_array().unwrap();let expressions:Vec<_>=terms.iter().map(|term|Atom::parse(term["coefficient"].as_str().unwrap(),ns,Default::default()).unwrap()).collect();
  // Admission validates that the consistent namespace renaming has no remaining free inputs.
  let _admission=Atom::evaluator_multiple(&expressions,&parameters).direct_translation(true).horner_iterations(0).cores(1).build().unwrap();
  let one_row=results["domains"][0]["batches"].as_array().unwrap().iter().find(|b|b["rows"]==1).unwrap();let numeric:Vec<_>=parameters.iter().zip(one_row["input"].as_array().unwrap()).map(|(p,z)|{let re=z[0]["rational"].as_str().unwrap();let im=z[1]["rational"].as_str().unwrap();let value=Atom::parse(&format!("({re})+({im})*𝑖"),ns,Default::default()).unwrap();Replacement::new(p.clone(),value)}).collect();
  let mut identities=Vec::new();for(index,(term,expression))in terms.iter().zip(expressions).enumerate(){let rank:u32=term["powers"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as u32).sum();let dimension=numerator_dimension.checked_sub(rank).unwrap();let scaled=expression.replace_multiple(&replacements);let difference=(scaled-lambda.pow(dimension)*expression.clone()).expand();assert!(difference.is_zero(),"homogeneity {case} coefficient{index}");let substituted=expression.replace_multiple(&numeric).expand();identities.push(json!({"index":index,"powers":term["powers"],"coefficient_dimension":dimension,"scaling_identity_literal_zero":true,"selected_input_exact_coefficient":substituted.to_string(),"selected_input_exact_zero":substituted.is_zero()}));}
  let record=json!({"case":case,"numerator_dimension":numerator_dimension,"assignment_reason":"Each internal fermion propagator numerator contributes one mass dimension; gauge/Yukawa couplings and fixed external polarization vectors are dimensionless. All coefficient dimensions are then verified by exact Symbolica scaling, not inferred alone.","parameter_map":names.iter().zip(&short_names).zip(&dimensions).map(|((name,short),dimension)|json!({"qualified":name,"consistent_display_name":short,"dimension":dimension})).collect::<Vec<_>>(),"input_context_sample_ids":one_row["sample_ids"],"homogeneity":identities,"proof":"Symbolica simultaneous replacements and exact expansion of c(lambda*p,lambda*m)-lambda^(N-rank)*c are literal zero; namespace renaming is injective and evaluator admission accounts for every parameter"});
  eprintln!("HOMOGENEITY_PASS {case} {} coefficients",terms.len());cases.push(record);
 }
 let out=base.join("homogeneity.json");assert!(!out.exists());std::fs::write(out,serde_json::to_vec_pretty(&json!({"status":"passed","cases":cases,"scope":"Separate physical dimension diagnostic; no changes to retained raw numerical gates"})).unwrap()).unwrap();
}
